(function(g){g.__QURAN_DATA=g.__QURAN_DATA||{};g.__QURAN_DATA["tamil-063"]={"sura":63,"name_ar":"المنافقون","name_en":"Al-Munafiqun","verses":11,"source":"https://www.tamililquran.com/tafsiribnkathir.php","count":11,"missing":[],"data":{"1":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=63&ayah=4\" class=\"link\">63:4</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 63:4 ஐ பார்க்கவும்"},"2":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=63&ayah=4\" class=\"link\">63:4</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 63:4 ஐ பார்க்கவும்"},"3":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=63&ayah=4\" class=\"link\">63:4</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 63:4 ஐ பார்க்கவும்"},"4":{"html":"அத்தியாயம் 63 அல்முனாஃபிகூன் (நயவஞ்சகர்கள்)<br />\r\n<br />\r\n<strong>இது மதீனாவில் அருளப்பட்டது</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾بِسْمِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَنِ</span> <span class=\"quran-arabic-font text-success\">الرَّحِيمِ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\nஅளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.<br />\r\n<br />\r\n<strong>நயவஞ்சகர்களின் நிலையும் அவர்களது நடத்தைகளும்</strong><br />\r\n<br />\r\nநயவஞ்சகர்கள் நபி (ஸல்) அவர்களிடம் வந்தபோது தாங்கள் முஸ்லிம்கள் என்பது போல் காட்டிக்கொண்டார்கள் என்று உயர்ந்தோனாகிய அல்லாஹ் கூறுகிறான். உண்மையில் அவர்கள் முஸ்லிம்கள் அல்ல, மாறாக அதற்கு நேர்மாறானவர்களாகவே இருந்தார்கள். இதனால்தான் உயர்ந்தோனாகிய அல்லாஹ் கூறினான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِذَا</span> <span class=\"quran-arabic-font text-success\">جَآءَكَ</span> <span class=\"quran-arabic-font text-success\">الْمُنَافِقُونَ</span> <span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">نَشْهَدُ</span> <span class=\"quran-arabic-font text-success\">إِنَّكَ</span> <span class=\"quran-arabic-font text-success\">لَرَسُولُ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ﴿</span><br />\r\n<br />\r\n(நயவஞ்சகர்கள் உம்மிடம் வரும்போது, \"நிச்சயமாக நீர் அல்லாஹ்வின் தூதர் என்று நாங்கள் சாட்சி கூறுகிறோம்\" எனக் கூறுகின்றனர்.) அதாவது, நயவஞ்சகர்கள் உம்மிடம் வரும்போது, இந்த வாசகத்தை வெளிப்படுத்தி தாங்கள் ஈமான் கொண்டிருப்பது போல் காட்டிக்கொள்கின்றனர். அவர்களது கூற்றில் எவ்வித உண்மையும் இல்லை என்பதை அல்லாஹ் அறிவிக்கிறான். இதனால்தான் அவன் கூறினான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">يَعْلَمُ</span> <span class=\"quran-arabic-font text-success\">إِنَّكَ</span> <span class=\"quran-arabic-font text-success\">لَرَسُولُهُ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக நீர் அவனுடைய தூதர் என்பதை அல்லாஹ் நன்கறிவான்.) பின்னர் கூறினான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">يَشْهَدُ</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الْمُنَافِقِينَ</span> <span class=\"quran-arabic-font text-success\">لَكَاذِبُونَ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக நயவஞ்சகர்கள் பொய்யர்களே என்று அல்லாஹ் சாட்சியமளிக்கிறான்.) அதாவது, நபி (ஸல்) அவர்களைப் பற்றிய அவர்களது கூற்று உண்மையாக இருந்தபோதிலும், அவர்கள் பொய்யர்களே. ஏனெனில் அவர்கள் தங்கள் நாவினால் வெளிப்படுத்தியதை உள்ளத்தால் நம்பவில்லை. இதனால்தான் அவர்களது கொள்கை பொய்யானது என்று அல்லாஹ் அறிவித்தான். அல்லாஹ்வின் கூற்று:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾اتَّخَذُوا</span> <span class=\"quran-arabic-font text-success\">أَيْمَانَهُمْ</span> <span class=\"quran-arabic-font text-success\">جُنَّةً</span> <span class=\"quran-arabic-font text-success\">فَصَدُّواْ</span> <span class=\"quran-arabic-font text-success\">عَن</span> <span class=\"quran-arabic-font text-success\">سَبِيلِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ﴿</span><br />\r\n<br />\r\n(அவர்கள் தங்கள் சத்தியங்களைக் கேடயமாக ஆக்கிக்கொண்டார்கள். அதன் மூலம் அல்லாஹ்வின் பாதையை விட்டும் (மக்களைத்) தடுக்கிறார்கள்.) அதாவது, நயவஞ்சகர்கள் உண்மையில் தாங்கள் இல்லாத ஒன்றை இருப்பதாகப் பொய்யாகவும் பாவகரமாகவும் சத்தியம் செய்து, அதன் மூலம் முஸ்லிம்களிடமிருந்து தங்களைப் பாதுகாத்துக் கொள்கிறார்கள். அவர்களது பொய்களை அறியாத காரணத்தால் சில முஸ்லிம்கள் ஏமாற்றமடைந்தனர்; அவர்கள் முஸ்லிம்கள் என்றே கருதிவிட்டனர். சில முஸ்லிம்கள் நயவஞ்சகர்களின் பேச்சை நம்பி, அவர்களது வெளிப்படையான செயல்களைப் பின்பற்றவும் செய்தனர். இருப்பினும், நயவஞ்சகர்கள் உள்ளூர இஸ்லாத்தையும் அதன் மக்களையும் அழிக்கவே விரும்புகிறார்கள். அதனால்தான் அவர்களை நம்புவது பலருக்குப் பெரும் தீங்கை விளைவிக்கும். இதனால்தான் அல்லாஹ் அடுத்துக் கூறினான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَصَدُّواْ</span> <span class=\"quran-arabic-font text-success\">عَن</span> <span class=\"quran-arabic-font text-success\">سَبِيلِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">إِنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">سَآءَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">يَعْمَلُونَ﴿</span><br />\r\n<br />\r\n(இவ்வாறு அவர்கள் அல்லாஹ்வின் பாதையை விட்டும் (மக்களைத்) தடுத்தனர். நிச்சயமாக அவர்கள் செய்து கொண்டிருந்தவை மிகவும் தீயவை.)<br />\r\n<br />\r\nஅல்லாஹ் கூறினான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">بِأَنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواّ</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">كَفَرُوا</span> <span class=\"quran-arabic-font text-success\">فَطُبِعَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">قُلُوبِهِمْ</span> <span class=\"quran-arabic-font text-success\">فَهُمْ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَفْقَهُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அது ஏனென்றால், அவர்கள் ஈமான் கொண்டு பின்னர் நிராகரித்தார்கள்; எனவே அவர்களது இதயங்கள் முத்திரையிடப்பட்டுவிட்டன. ஆதலால் அவர்கள் (நேர்வழியை) விளங்கிக்கொள்ள மாட்டார்கள்.) அதாவது, அவர்கள் ஈமானிலிருந்து நிராகரிப்பிற்குத் திரும்பியதாலும், நேர்வழிக்கு மாற்றாக வழிகேட்டைத் தேர்ந்தெடுத்ததாலும், அவர்களை நயவஞ்சகர்களாகவே இருக்க அல்லாஹ் விதித்துவிட்டான். எனவே அல்லாஹ் அவர்களது இதயங்களுக்கு முத்திரையிட்டுவிட்டான். அதன் காரணமாக அவர்களால் நேர்வழியைப் புரிந்துகொள்ள முடியாது, எந்த நன்மையும் அவர்களது இதயங்களை அடையாது. உண்மையாகவே அவர்களது இதயங்கள் எதையும் விளங்குவதில்லை, நேர்வழியை அடைவதுமில்லை.<br />\r\n<br />\r\nஅல்லாஹ் கூறினான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَإِذَا</span> <span class=\"quran-arabic-font text-success\">رَأَيْتَهُمْ</span> <span class=\"quran-arabic-font text-success\">تُعْجِبُكَ</span> <span class=\"quran-arabic-font text-success\">أَجْسَامُهُمْ</span> <span class=\"quran-arabic-font text-success\">وَإِن</span> <span class=\"quran-arabic-font text-success\">يَقُولُواْ</span> <span class=\"quran-arabic-font text-success\">تَسْمَعْ</span> <span class=\"quran-arabic-font text-success\">لِقَوْلِهِمْ</span> <span class=\"quran-arabic-font text-success\">كَأَنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">خُشُبٌ</span> <span class=\"quran-arabic-font text-success\">مُّسَنَّدَةٌ﴿</span><br />\r\n<br />\r\n(நீர் அவர்களைக் காணும்போது, அவர்களது உருவங்கள் உம்மை வியப்பில் ஆழ்த்தும்; அவர்கள் பேசினால், அவர்களது பேச்சை நீர் (கவனமாக) கேட்பீர். அவர்கள் (சுவரில்) சாய்த்து வைக்கப்பட்ட மரக்கட்டைகளைப் போன்றவர்கள்.) அதாவது, நயவஞ்சகர்கள் அழகான வெளித்தோற்றமும் சிறந்த பேச்சாற்றலும் கொண்டவர்கள். அவர்கள் பேசும்போது எவரும் அவர்களது சொல்லாற்றலைக் கேட்க விரும்புவார்கள். அவர்கள் (உயிரோட்டமில்லாத) வெறும் உருவங்கள் என்பதாலேயே (சாய்த்து வைக்கப்பட்ட மரக்கட்டைகள் என்று) வருணிக்கப்பட்டுள்ளார்கள். இருப்பினும், அவர்கள் உண்மையில் மிகவும் பலவீனமானவர்கள், பயமும் கோழைத்தனமும் நிறைந்தவர்கள். அல்லாஹ்வின் கூற்று:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾يَحْسَبُونَ</span> <span class=\"quran-arabic-font text-success\">كُلَّ</span> <span class=\"quran-arabic-font text-success\">صَيْحَةٍ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ﴿</span><br />\r\n<br />\r\n(ஒவ்வொரு சப்தமும் தங்களுக்கு எதிராகவே இருப்பதாக அவர்கள் கருதுகிறார்கள்.) அதாவது, ஏதேனும் ஒரு சம்பவம் நிகழ்ந்தாலோ அல்லது அச்சமூட்டும் காரியம் நடந்தாலோ, அது தங்களைத் தாக்கவே வருகிறது என்று அவர்கள் அஞ்சுகிறார்கள். இது அவர்களது கோழைத்தனத்தைக் காட்டுகிறது. அவர்களைப் பற்றி அல்லாஹ் கூறியது போல:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَشِحَّةً</span> <span class=\"quran-arabic-font text-success\">عَلَيْكُمْ</span> <span class=\"quran-arabic-font text-success\">فَإِذَا</span> <span class=\"quran-arabic-font text-success\">جَآءَ</span> <span class=\"quran-arabic-font text-success\">الْخَوْفُ</span> <span class=\"quran-arabic-font text-success\">رَأَيْتَهُمْ</span> <span class=\"quran-arabic-font text-success\">يَنظُرُونَ</span> <span class=\"quran-arabic-font text-success\">إِلَيْكَ</span> <span class=\"quran-arabic-font text-success\">تَدورُ</span> <span class=\"quran-arabic-font text-success\">أَعْيُنُهُمْ</span> <span class=\"quran-arabic-font text-success\">كَالَّذِى</span> <span class=\"quran-arabic-font text-success\">يُغْشَى</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْمَوْتِ</span> <span class=\"quran-arabic-font text-success\">فَإِذَا</span> <span class=\"quran-arabic-font text-success\">ذَهَبَ</span> <span class=\"quran-arabic-font text-success\">الْخَوْفُ</span> <span class=\"quran-arabic-font text-success\">سَلَقُوكُم</span> <span class=\"quran-arabic-font text-success\">بِأَلْسِنَةٍ</span> <span class=\"quran-arabic-font text-success\">حِدَادٍ</span> <span class=\"quran-arabic-font text-success\">أَشِحَّةً</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْخَيْرِ</span> <span class=\"quran-arabic-font text-success\">أُولَئِكَ</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">يُؤْمِنُواْ</span> <span class=\"quran-arabic-font text-success\">فَأَحْبَطَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">أَعْمَالَهُمْ</span> <span class=\"quran-arabic-font text-success\">وَكَانَ</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">يَسِيراً</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அவர்கள் உங்கள் மீது கஞ்சத்தனம் கொண்டவர்கள். அச்சம் வரும்போது, மரணத் தறுவாயில் இருப்பவனைப் போல் அவர்களது கண்கள் சுழல, அவர்கள் உம்மைப் பார்ப்பதை நீர் காண்பீர். அந்த அச்சம் நீங்கிவிட்டால், நன்மையின் மீது கஞ்சத்தனம் கொண்டவர்களாக, கூர்மையான நாவுகளால் உங்களைக் காயப்படுத்துவார்கள். அத்தகையோர் ஈமான் கொள்ளவில்லை; எனவே அல்லாஹ் அவர்களது செயல்களைப் பயனில்லாததாக்கிவிட்டான். இது அல்லாஹ்விற்கு மிகவும் எளிதானதாகும்.) (<a href=\"qurandisp.php?sura=33&ayah=19\" class=\"link\">33:19</a>). அவர்கள் சாரம் இல்லாத வெறும் உருவங்களே. இதனால்தான் அல்லாஹ் கூறினான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾هُمُ</span> <span class=\"quran-arabic-font text-success\">الْعَدُوُّ</span> <span class=\"quran-arabic-font text-success\">فَاحْذَرْهُمْ</span> <span class=\"quran-arabic-font text-success\">قَاتَلَهُمُ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">أَنَّى</span> <span class=\"quran-arabic-font text-success\">يُؤْفَكُونَ﴿</span><br />\r\n<br />\r\n(அவர்களே எதிரிகள், எனவே அவர்களைப் பற்றி எச்சரிக்கையாக இருப்பீராக. அல்லாஹ் அவர்களை அழிப்பானாக! அவர்கள் எங்கு திசை திருப்பப்படுகிறார்கள்?) அதாவது, அவர்கள் நேர்வழியை விட்டு வழிகேட்டிற்கு எவ்வாறு இட்டுச் செல்லப்படுகிறார்கள்?<br />\r\n<br />\r\nஇமாம் அஹ்மத் அவர்கள் பதிவு செய்துள்ளார்கள்: அபூ ஹுரைரா (ரழி) அவர்கள் அறிவிக்கிறார்கள், நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾</span>«<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">لِلْمُنَافِقِينَ</span> <span class=\"quran-arabic-font text-success\">عَلَامَاتٍ</span> <span class=\"quran-arabic-font text-success\">يُعْرَفُونَ</span> <span class=\"quran-arabic-font text-success\">بِهَا</span>: <span class=\"quran-arabic-font text-success\">تَحِيَّتُهُمْ</span> <span class=\"quran-arabic-font text-success\">لَعْنَةٌ</span> <span class=\"quran-arabic-font text-success\">وَطَعَامُهُمْ</span> <span class=\"quran-arabic-font text-success\">نُهْبَةٌ</span> <span class=\"quran-arabic-font text-success\">وَغَنِيمَتُهُمْ</span> <span class=\"quran-arabic-font text-success\">غُلُولٌ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يَقْرَبُونَ</span> <span class=\"quran-arabic-font text-success\">الْمَسَاجِدَ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">هَجْرًا،</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">يَأْتُونَ</span> <span class=\"quran-arabic-font text-success\">الصَّلَاةَ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">دَبْرًا،</span> <span class=\"quran-arabic-font text-success\">مُسْتَكْبِرِينَ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يَأْلَفُونَ</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">يُؤْلَفُونَ،</span> <span class=\"quran-arabic-font text-success\">خُشُبٌ</span> <span class=\"quran-arabic-font text-success\">بِاللَّيْلِ</span> <span class=\"quran-arabic-font text-success\">صُخُبٌ</span> <span class=\"quran-arabic-font text-success\">بِالنَّهَارِ</span> <span class=\"quran-arabic-font text-success\">وفِي</span> <span class=\"quran-arabic-font text-success\">رِوَايَةٍ</span> <span class=\"quran-arabic-font text-success\">سُخُبٌ</span> <span class=\"quran-arabic-font text-success\">بِالنَّهَار</span>»<span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நயவஞ்சகர்களுக்குச் சில அடையாளங்கள் உள்ளன, அதன் மூலம் அவர்கள் அறியப்படுவார்கள்: அவர்களது வாழ்த்து ஒரு சாபமாகும், அவர்களது உணவு கொள்ளையடிக்கப்பட்டதாகும், அவர்கள் எடுக்கும் போர்ச்செல்வம் (கனீமத்) மோசடி செய்யப்பட்டதாகும். அவர்கள் மஸ்ஜித்களை விட்டு ஒதுங்கியே இருப்பார்கள். தொழுகையின் கடைசி நேரத்திலன்றி அவர்கள் வரமாட்டார்கள். அவர்கள் பெருமைக்காரர்கள்; அவர்கள் மற்றவர்களுடன் இணக்கமாகவும் இருக்க மாட்டார்கள், மற்றவர்கள் அவர்களுடன் இணக்கமாக இருப்பதையும் விரும்பமாட்டார்கள். அவர்கள் இரவில் மரக்கட்டைகளைப் போன்றும், பகலில் சத்தமிடுபவர்களாகவும் இருப்பார்கள். வேறொரு அறிவிப்பில்: பகலில் கூச்சலிடுபவர்கள் (என்றும் வந்துள்ளது).)<br />\r\n<br />","text":"அத்தியாயம் 63 அல்முனாஃபிகூன் (நயவஞ்சகர்கள்)\n\r\n\n\r\nஇது மதீனாவில் அருளப்பட்டது\n\r\n\n\r\n﴾بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ ﴿\n\r\n\n\r\nஅளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.\n\r\n\n\r\nநயவஞ்சகர்களின் நிலையும் அவர்களது நடத்தைகளும்\n\r\n\n\r\nநயவஞ்சகர்கள் நபி (ஸல்) அவர்களிடம் வந்தபோது தாங்கள் முஸ்லிம்கள் என்பது போல் காட்டிக்கொண்டார்கள் என்று உயர்ந்தோனாகிய அல்லாஹ் கூறுகிறான். உண்மையில் அவர்கள் முஸ்லிம்கள் அல்ல, மாறாக அதற்கு நேர்மாறானவர்களாகவே இருந்தார்கள். இதனால்தான் உயர்ந்தோனாகிய அல்லாஹ் கூறினான்:\n\r\n﴾إِذَا جَآءَكَ الْمُنَافِقُونَ قَالُواْ نَشْهَدُ إِنَّكَ لَرَسُولُ اللَّهِ﴿\n\r\n\n\r\n(நயவஞ்சகர்கள் உம்மிடம் வரும்போது, \"நிச்சயமாக நீர் அல்லாஹ்வின் தூதர் என்று நாங்கள் சாட்சி கூறுகிறோம்\" எனக் கூறுகின்றனர்.) அதாவது, நயவஞ்சகர்கள் உம்மிடம் வரும்போது, இந்த வாசகத்தை வெளிப்படுத்தி தாங்கள் ஈமான் கொண்டிருப்பது போல் காட்டிக்கொள்கின்றனர். அவர்களது கூற்றில் எவ்வித உண்மையும் இல்லை என்பதை அல்லாஹ் அறிவிக்கிறான். இதனால்தான் அவன் கூறினான்:\n\r\n﴾وَاللَّهُ يَعْلَمُ إِنَّكَ لَرَسُولُهُ﴿\n\r\n\n\r\n(நிச்சயமாக நீர் அவனுடைய தூதர் என்பதை அல்லாஹ் நன்கறிவான்.) பின்னர் கூறினான்:\n\r\n﴾وَاللَّهُ يَشْهَدُ إِنَّ الْمُنَافِقِينَ لَكَاذِبُونَ﴿\n\r\n\n\r\n(நிச்சயமாக நயவஞ்சகர்கள் பொய்யர்களே என்று அல்லாஹ் சாட்சியமளிக்கிறான்.) அதாவது, நபி (ஸல்) அவர்களைப் பற்றிய அவர்களது கூற்று உண்மையாக இருந்தபோதிலும், அவர்கள் பொய்யர்களே. ஏனெனில் அவர்கள் தங்கள் நாவினால் வெளிப்படுத்தியதை உள்ளத்தால் நம்பவில்லை. இதனால்தான் அவர்களது கொள்கை பொய்யானது என்று அல்லாஹ் அறிவித்தான். அல்லாஹ்வின் கூற்று:\n\r\n﴾اتَّخَذُوا أَيْمَانَهُمْ جُنَّةً فَصَدُّواْ عَن سَبِيلِ اللَّهِ﴿\n\r\n\n\r\n(அவர்கள் தங்கள் சத்தியங்களைக் கேடயமாக ஆக்கிக்கொண்டார்கள். அதன் மூலம் அல்லாஹ்வின் பாதையை விட்டும் (மக்களைத்) தடுக்கிறார்கள்.) அதாவது, நயவஞ்சகர்கள் உண்மையில் தாங்கள் இல்லாத ஒன்றை இருப்பதாகப் பொய்யாகவும் பாவகரமாகவும் சத்தியம் செய்து, அதன் மூலம் முஸ்லிம்களிடமிருந்து தங்களைப் பாதுகாத்துக் கொள்கிறார்கள். அவர்களது பொய்களை அறியாத காரணத்தால் சில முஸ்லிம்கள் ஏமாற்றமடைந்தனர்; அவர்கள் முஸ்லிம்கள் என்றே கருதிவிட்டனர். சில முஸ்லிம்கள் நயவஞ்சகர்களின் பேச்சை நம்பி, அவர்களது வெளிப்படையான செயல்களைப் பின்பற்றவும் செய்தனர். இருப்பினும், நயவஞ்சகர்கள் உள்ளூர இஸ்லாத்தையும் அதன் மக்களையும் அழிக்கவே விரும்புகிறார்கள். அதனால்தான் அவர்களை நம்புவது பலருக்குப் பெரும் தீங்கை விளைவிக்கும். இதனால்தான் அல்லாஹ் அடுத்துக் கூறினான்:\n\r\n﴾فَصَدُّواْ عَن سَبِيلِ اللَّهِ إِنَّهُمْ سَآءَ مَا كَانُواْ يَعْمَلُونَ﴿\n\r\n\n\r\n(இவ்வாறு அவர்கள் அல்லாஹ்வின் பாதையை விட்டும் (மக்களைத்) தடுத்தனர். நிச்சயமாக அவர்கள் செய்து கொண்டிருந்தவை மிகவும் தீயவை.)\n\r\n\n\r\nஅல்லாஹ் கூறினான்:\n\r\n﴾ذَلِكَ بِأَنَّهُمْ ءَامَنُواّ ثُمَّ كَفَرُوا فَطُبِعَ عَلَى قُلُوبِهِمْ فَهُمْ لاَ يَفْقَهُونَ ﴿\n\r\n\n\r\n(அது ஏனென்றால், அவர்கள் ஈமான் கொண்டு பின்னர் நிராகரித்தார்கள்; எனவே அவர்களது இதயங்கள் முத்திரையிடப்பட்டுவிட்டன. ஆதலால் அவர்கள் (நேர்வழியை) விளங்கிக்கொள்ள மாட்டார்கள்.) அதாவது, அவர்கள் ஈமானிலிருந்து நிராகரிப்பிற்குத் திரும்பியதாலும், நேர்வழிக்கு மாற்றாக வழிகேட்டைத் தேர்ந்தெடுத்ததாலும், அவர்களை நயவஞ்சகர்களாகவே இருக்க அல்லாஹ் விதித்துவிட்டான். எனவே அல்லாஹ் அவர்களது இதயங்களுக்கு முத்திரையிட்டுவிட்டான். அதன் காரணமாக அவர்களால் நேர்வழியைப் புரிந்துகொள்ள முடியாது, எந்த நன்மையும் அவர்களது இதயங்களை அடையாது. உண்மையாகவே அவர்களது இதயங்கள் எதையும் விளங்குவதில்லை, நேர்வழியை அடைவதுமில்லை.\n\r\n\n\r\nஅல்லாஹ் கூறினான்:\n\r\n﴾وَإِذَا رَأَيْتَهُمْ تُعْجِبُكَ أَجْسَامُهُمْ وَإِن يَقُولُواْ تَسْمَعْ لِقَوْلِهِمْ كَأَنَّهُمْ خُشُبٌ مُّسَنَّدَةٌ﴿\n\r\n\n\r\n(நீர் அவர்களைக் காணும்போது, அவர்களது உருவங்கள் உம்மை வியப்பில் ஆழ்த்தும்; அவர்கள் பேசினால், அவர்களது பேச்சை நீர் (கவனமாக) கேட்பீர். அவர்கள் (சுவரில்) சாய்த்து வைக்கப்பட்ட மரக்கட்டைகளைப் போன்றவர்கள்.) அதாவது, நயவஞ்சகர்கள் அழகான வெளித்தோற்றமும் சிறந்த பேச்சாற்றலும் கொண்டவர்கள். அவர்கள் பேசும்போது எவரும் அவர்களது சொல்லாற்றலைக் கேட்க விரும்புவார்கள். அவர்கள் (உயிரோட்டமில்லாத) வெறும் உருவங்கள் என்பதாலேயே (சாய்த்து வைக்கப்பட்ட மரக்கட்டைகள் என்று) வருணிக்கப்பட்டுள்ளார்கள். இருப்பினும், அவர்கள் உண்மையில் மிகவும் பலவீனமானவர்கள், பயமும் கோழைத்தனமும் நிறைந்தவர்கள். அல்லாஹ்வின் கூற்று:\n\r\n﴾يَحْسَبُونَ كُلَّ صَيْحَةٍ عَلَيْهِمْ﴿\n\r\n\n\r\n(ஒவ்வொரு சப்தமும் தங்களுக்கு எதிராகவே இருப்பதாக அவர்கள் கருதுகிறார்கள்.) அதாவது, ஏதேனும் ஒரு சம்பவம் நிகழ்ந்தாலோ அல்லது அச்சமூட்டும் காரியம் நடந்தாலோ, அது தங்களைத் தாக்கவே வருகிறது என்று அவர்கள் அஞ்சுகிறார்கள். இது அவர்களது கோழைத்தனத்தைக் காட்டுகிறது. அவர்களைப் பற்றி அல்லாஹ் கூறியது போல:\n\r\n﴾أَشِحَّةً عَلَيْكُمْ فَإِذَا جَآءَ الْخَوْفُ رَأَيْتَهُمْ يَنظُرُونَ إِلَيْكَ تَدورُ أَعْيُنُهُمْ كَالَّذِى يُغْشَى عَلَيْهِ مِنَ الْمَوْتِ فَإِذَا ذَهَبَ الْخَوْفُ سَلَقُوكُم بِأَلْسِنَةٍ حِدَادٍ أَشِحَّةً عَلَى الْخَيْرِ أُولَئِكَ لَمْ يُؤْمِنُواْ فَأَحْبَطَ اللَّهُ أَعْمَالَهُمْ وَكَانَ ذَلِكَ عَلَى اللَّهِ يَسِيراً ﴿\n\r\n\n\r\n(அவர்கள் உங்கள் மீது கஞ்சத்தனம் கொண்டவர்கள். அச்சம் வரும்போது, மரணத் தறுவாயில் இருப்பவனைப் போல் அவர்களது கண்கள் சுழல, அவர்கள் உம்மைப் பார்ப்பதை நீர் காண்பீர். அந்த அச்சம் நீங்கிவிட்டால், நன்மையின் மீது கஞ்சத்தனம் கொண்டவர்களாக, கூர்மையான நாவுகளால் உங்களைக் காயப்படுத்துவார்கள். அத்தகையோர் ஈமான் கொள்ளவில்லை; எனவே அல்லாஹ் அவர்களது செயல்களைப் பயனில்லாததாக்கிவிட்டான். இது அல்லாஹ்விற்கு மிகவும் எளிதானதாகும்.) (33:19). அவர்கள் சாரம் இல்லாத வெறும் உருவங்களே. இதனால்தான் அல்லாஹ் கூறினான்:\n\r\n﴾هُمُ الْعَدُوُّ فَاحْذَرْهُمْ قَاتَلَهُمُ اللَّهُ أَنَّى يُؤْفَكُونَ﴿\n\r\n\n\r\n(அவர்களே எதிரிகள், எனவே அவர்களைப் பற்றி எச்சரிக்கையாக இருப்பீராக. அல்லாஹ் அவர்களை அழிப்பானாக! அவர்கள் எங்கு திசை திருப்பப்படுகிறார்கள்?) அதாவது, அவர்கள் நேர்வழியை விட்டு வழிகேட்டிற்கு எவ்வாறு இட்டுச் செல்லப்படுகிறார்கள்?\n\r\n\n\r\nஇமாம் அஹ்மத் அவர்கள் பதிவு செய்துள்ளார்கள்: அபூ ஹுரைரா (ரழி) அவர்கள் அறிவிக்கிறார்கள், நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n﴾«إِنَّ لِلْمُنَافِقِينَ عَلَامَاتٍ يُعْرَفُونَ بِهَا: تَحِيَّتُهُمْ لَعْنَةٌ وَطَعَامُهُمْ نُهْبَةٌ وَغَنِيمَتُهُمْ غُلُولٌ لَا يَقْرَبُونَ الْمَسَاجِدَ إِلَّا هَجْرًا، وَلَا يَأْتُونَ الصَّلَاةَ إِلَّا دَبْرًا، مُسْتَكْبِرِينَ لَا يَأْلَفُونَ وَلَا يُؤْلَفُونَ، خُشُبٌ بِاللَّيْلِ صُخُبٌ بِالنَّهَارِ وفِي رِوَايَةٍ سُخُبٌ بِالنَّهَار»﴿\n\r\n\n\r\n(நயவஞ்சகர்களுக்குச் சில அடையாளங்கள் உள்ளன, அதன் மூலம் அவர்கள் அறியப்படுவார்கள்: அவர்களது வாழ்த்து ஒரு சாபமாகும், அவர்களது உணவு கொள்ளையடிக்கப்பட்டதாகும், அவர்கள் எடுக்கும் போர்ச்செல்வம் (கனீமத்) மோசடி செய்யப்பட்டதாகும். அவர்கள் மஸ்ஜித்களை விட்டு ஒதுங்கியே இருப்பார்கள். தொழுகையின் கடைசி நேரத்திலன்றி அவர்கள் வரமாட்டார்கள். அவர்கள் பெருமைக்காரர்கள்; அவர்கள் மற்றவர்களுடன் இணக்கமாகவும் இருக்க மாட்டார்கள், மற்றவர்கள் அவர்களுடன் இணக்கமாக இருப்பதையும் விரும்பமாட்டார்கள். அவர்கள் இரவில் மரக்கட்டைகளைப் போன்றும், பகலில் சத்தமிடுபவர்களாகவும் இருப்பார்கள். வேறொரு அறிவிப்பில்: பகலில் கூச்சலிடுபவர்கள் (என்றும் வந்துள்ளது).)"},"5":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=63&ayah=8\" class=\"link\">63:8</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 63:8 ஐ பார்க்கவும்"},"6":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=63&ayah=8\" class=\"link\">63:8</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 63:8 ஐ பார்க்கவும்"},"7":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=63&ayah=8\" class=\"link\">63:8</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 63:8 ஐ பார்க்கவும்"},"8":{"html":"<strong>தங்களுக்காக மன்னிப்புத் தேடும்படி அல்லாஹ்வின் தூதரிடம் வேண்டுவதற்கு நயவஞ்சகர்கள் முன்வரவில்லை</strong><br />\r\n<br />\r\n<br />\r\nஅல்லாஹ்வின் சாபத்திற்குரிய நயவஞ்சகர்களைப் பற்றி கண்ணியத்திற்குரிய அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِذَا</span> <span class=\"quran-arabic-font text-success\">قِيلَ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">تَعَالَوْاْ</span> <span class=\"quran-arabic-font text-success\">يَسْتَغْفِرْ</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">رَسُولُ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">لَوَّوْاْ</span> <span class=\"quran-arabic-font text-success\">رُءُوسَهُمْ</span><br />\r\n<br />\r\n<br />\r\n(அவர்களிடம்: \"வாருங்கள், அல்லாஹ்வின் தூதர் உங்களுக்காக அல்லாஹ்விடம் பாவமன்னிப்புத் தேடுவார்கள்\" எனக் கூறப்பட்டால், அவர்கள் தங்கள் தலைகளைத் திருப்பிக் கொள்கிறார்கள்.) அதாவது, அவர்கள் பெருமையின் காரணமாக இதைப் புறக்கணித்து, தாங்கள் அழைக்கப்படும் விஷயத்தை இழிவுபடுத்தி, அதிலிருந்து விலகிச் செல்கிறார்கள். இதனால்தான் அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَرَأَيْتَهُمْ</span> <span class=\"quran-arabic-font text-success\">يَصُدُّونَ</span> <span class=\"quran-arabic-font text-success\">وَهُم</span> <span class=\"quran-arabic-font text-success\">مُّسْتَكْبِرُونَ</span><br />\r\n<br />\r\n<br />\r\n(மேலும், அவர்கள் பெருமையுடன் தங்கள் முகங்களைத் திருப்பிக் கொள்வதை நீர் காண்பீர்.) அவர்களின் இத்தகைய நடத்தைக்காக அவர்களைத் தண்டிக்கும் விதமாக அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">سَوَآءٌ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">أَسْتَغْفَرْتَ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">تَسْتَغْفِرْ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">لَن</span> <span class=\"quran-arabic-font text-success\">يَغْفِرَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَهْدِى</span> <span class=\"quran-arabic-font text-success\">الْقَوْمَ</span> <span class=\"quran-arabic-font text-success\">الْفَـسِقِينَ</span><br />\r\n<br />\r\n<br />\r\n(நீர் அவர்களுக்காகப் பாவமன்னிப்புத் தேடினாலும் அல்லது தேடாவிட்டாலும் அவர்களுக்குச் சமமே; அல்லாஹ் அவர்களை ஒருபோதும் மன்னிக்க மாட்டான். நிச்சயமாக, அல்லாஹ் வரம்பு மீறிய பாவிகளுக்கு நேர்வழி காட்டமாட்டான்.) ஸூரா பராஆவில் (அத்-தவ்பா) அல்லாஹ் கூறியது போன்று, இது குறித்த விளக்கம் அந்த அத்தியாயத்திலேயே ஏற்கனவே இடம்பெற்றுள்ளது. அது தொடர்பான சில ஹதீஸ்களை இங்கே நாம் குறிப்பிடுவோம். ஸலஃபுகள் (முன்னோர்) பலர் இந்த வசனங்கள் அனைத்தும் அப்துல்லாஹ் பின் உபய் பின் ஸலூல் விஷயத்திலேயே அருளப்பட்டதாகக் குறிப்பிட்டுள்ளனர். அல்லாஹ் நாடினால் இது குறித்து விரிவாகக் காண்போம்; அவன் மீதே நாம் முழுமையாகப் பாரத்தைச் சாட்டுகிறோம்.<br />\r\n<br />\r\n<br />\r\nஹும் அல்லதீன யகூலூன...<br />\r\n<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">هُمُ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">يَقُولُونَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">تُنفِقُواْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">عِندَ</span> <span class=\"quran-arabic-font text-success\">رَسُولِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">يَنفَضُّواْ</span> <span class=\"quran-arabic-font text-success\">وَلِلَّهِ</span> <span class=\"quran-arabic-font text-success\">خَزَآئِنُ</span> <span class=\"quran-arabic-font text-success\">السَّمَـوَتِ</span> <span class=\"quran-arabic-font text-success\">وَالاٌّرْضِ</span> <span class=\"quran-arabic-font text-success\">وَلَـكِنَّ</span> <span class=\"quran-arabic-font text-success\">الْمُنَـفِقِينَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَفْقَهُونَ</span> - <span class=\"quran-arabic-font text-success\">يَقُولُونَ</span> <span class=\"quran-arabic-font text-success\">لَئِن</span> <span class=\"quran-arabic-font text-success\">رَّجَعْنَا</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">الْمَدِينَةِ</span> <span class=\"quran-arabic-font text-success\">لَيُخْرِجَنَّ</span> <span class=\"quran-arabic-font text-success\">الاٌّعَزُّ</span> <span class=\"quran-arabic-font text-success\">مِنْهَا</span> <span class=\"quran-arabic-font text-success\">الاٌّذَلَّ</span> <span class=\"quran-arabic-font text-success\">وَلِلَّهِ</span> <span class=\"quran-arabic-font text-success\">الْعِزَّةُ</span> <span class=\"quran-arabic-font text-success\">وَلِرَسُولِهِ</span> <span class=\"quran-arabic-font text-success\">وَلِلْمُؤْمِنِينَ</span> <span class=\"quran-arabic-font text-success\">وَلَـكِنَّ</span> <span class=\"quran-arabic-font text-success\">الْمُنَـفِقِينَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَعْلَمُونَ</span><br />\r\n<br />\r\n<br />\r\n(அவர்கள்தான்: \"அல்லாஹ்வின் தூதருடன் இருப்பவர்கள் மீது (பொருட்களைச்) செலவு செய்யாதீர்கள்; அதனால் அவர்கள் (அவரை விட்டுப்) பிரிந்து சென்றுவிடுவார்கள்\" என்று கூறுகிறார்கள். வானங்கள் மற்றும் பூமியின் பொக்கிஷங்கள் அல்லாஹ்வுக்கே உரியன. எனினும், இந்நயவஞ்சகர்கள் விளங்கிக்கொள்ள மாட்டார்கள். அவர்கள்: \"நாங்கள் மதீனாவுக்குத் திரும்பினால், கண்ணியமானவர் இழிவானவரை அங்கிருந்து வெளியேற்றிவிடுவார்\" என்று கூறுகிறார்கள். கண்ணியம் அல்லாஹ்வுக்கும், அவனது தூதருக்கும், நம்பிக்கையாளர்களுக்கும் உரியதாகும். எனினும், இந்நயவஞ்சகர்கள் அறியமாட்டார்கள்.)<br />\r\n<br />\r\n<br />\r\nமுஹம்மது பின் இஸ்ஹாக் அவர்கள் தனது 'அஸ்-ஸீரா' நூலில் பின்வருமாறு கூறுகிறார்கள்: \"உஹுதுப் போர் முடிந்த பிறகு, நபி (ஸல்) அவர்கள் மதீனாவிற்குத் திரும்பினார்கள். இப்னு ஷிஹாப் எனக்கு அறிவித்தபடி, அப்துல்லாஹ் பின் உபய் பின் ஸலூல் ஒவ்வொரு வெள்ளிக்கிழமையும் ஜுமுஆ குத்பாவுக்கு முன்பாக நபி (ஸல்) அவர்கள் மின்பரில் அமர்ந்திருக்கும்போது எழுந்து நிற்பார். அவர் தனது சமூகத்தின் தலைவராக இருந்ததால் யாரும் அவரைத் தடுக்க மாட்டார்கள். அவர் கூறுவார்: 'மக்களே! உங்களிடையே அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இருக்கிறார்கள். அவர்கள் மூலம் அல்லாஹ் நமக்குக் கண்ணியத்தை அளித்துள்ளான், உங்களுக்கு வலிமையை வழங்கியுள்ளான். அவருக்கு ஆதரவளியுங்கள், அவரைக் கண்ணியப்படுத்துங்கள், அவருக்குச் செவிசாய்த்துக் கீழ்ப்படியுங்கள்.' இவ்வாறு கூறிவிட்டு அவர் அமர்வார். உஹுதுப் போரில் மூன்றில் ஒரு பங்கு படையுடன் அவர் பாதியிலேயே மதீனாவிற்குத் திரும்பிச் சென்ற பிறகும், அதே போன்று பேச எழுந்து நின்றார். ஆனால் முஸ்லிம்கள் அவரது ஆடையைப் பிடித்து இழுத்து, 'அல்லாஹ்வின் எதிரியே! அமர். நீ செய்த காரியத்திற்குப் பிறகு இங்கிருந்து பேச உனக்குத் தகுதியில்லை' என்றார்கள். உடனே அவர் மக்களின் வரிசைகளைத் தாண்டி மஸ்ஜிதை விட்டு வெளியேறினார். 'அல்லாஹ்வின் மீது ஆணையாக, நான் அவருக்கு ஆதரவாகப் பேச விரும்பியபோது ஏதோ ஒரு பெரும் குற்றத்தைச் செய்தது போன்று என்னை நடத்துகிறார்களே' என்று முணுமுணுத்துச் சென்றார். மஸ்ஜிதின் வாயிலில் நின்றிருந்த அன்சாரிகள் என்ன நடந்தது எனக் கேட்டபோது, 'நான் அவருக்கு ஆதரவாகப் பேச எழுந்தேன், ஆனால் அவரது தோழர்கள் என் மேல் பாய்ந்து என்னைக் கண்டித்தார்கள்' என்றார். அதற்கு அவர்கள், 'உமக்குக் கேடுதான்! திரும்பிச் செல்லும், அல்லாஹ்வின் தூதர் (ஸல்) உம்மை மன்னிக்கும்படி அல்லாஹ்விடம் வேண்டுவார்கள்' என்றனர். ஆனால் அவரோ, 'அல்லாஹ்வின் மீது ஆணையாக, அவர் எனக்காக மன்னிப்புக் கேட்பதை நான் விரும்பவில்லை' என்று கூறிவிட்டார்.\"<br />\r\n<br />\r\n<br />\r\nகதாதா மற்றும் அஸ்-ஸுத்தி ஆகியோர் கூறுகிறார்கள்: \"இந்த வசனம் அப்துல்லாஹ் பின் உபய் குறித்து அருளப்பட்டது. அவனது இளம் உறவினர் ஒருவர் நபி (ஸல்) அவர்களிடம் வந்து, அப்துல்லாஹ் பேசிய ஒரு மோசமான பேச்சைத் தெரிவித்தார். நபி (ஸல்) அவர்கள் அவனை அழைத்தபோது, தான் அவ்வாறு கூறவில்லை என அல்லாஹ்வின் மீது சத்தியம் செய்தான். அன்சாரிகளும் அந்தச் சிறுவனைக் கண்டித்தனர். ஆனால் அல்லாஹ் உண்மையை (வசனமாக) இறக்கினான். பிறகு அவனிடம் 'அல்லாஹ்வின் தூதரிடம் செல்லும்' எனக் கூறப்பட்டபோது, அவன் தன் தலையைத் திருப்பிக்கொண்டு அதைச் செய்ய மறுத்துவிட்டான்.\"<br />\r\n<br />\r\n<br />\r\nமுஹம்மது பின் இஸ்ஹாக், முஹம்மது பின் யஹ்யா பின் ஹிப்பான், அப்துல்லாஹ் பின் அபீ பக்ர் மற்றும் ஆஸிம் பின் உமர் பின் கதாதா ஆகியோர் பனூ முஸ்தலிக் போர் பற்றி அறிவிக்கிறார்கள்: நபி (ஸல்) அவர்கள் அங்கு தங்கியிருந்தபோது, உமர் (ரழி) அவர்களின் பணியாளரான ஜஹ்ஜா பின் ஸயீத் அல்-கிஃபாரியும், ஸினான் பின் வப்ர் அல்-ஜுஹனீயும் நீருற்றைப் பயன்படுத்துவதில் சண்டையிட்டுக் கொண்டனர். ஸினான் 'அன்சாரிகளே!' என்றும், ஜஹ்ஜா 'முஹாஜிர்களே!' என்றும் உதவிக்கு அழைத்தனர். அப்போது ஸைத் பின் அர்கம் (ரழி) அவர்களும் சில அன்சாரிகளும் அப்துல்லாஹ் பின் உபய்யுடன் அமர்ந்திருந்தனர். நடந்ததைக் கேட்ட அவன், 'அவர்கள் நம் ஊரிலேயே நமக்குத் தொந்தரவு தருகிறார்கள். நமக்கும் இந்த வந்தேறிக் குறைஷிகளுக்கும் உள்ள நிலை: 'உன் நாயைக் கொழுக்க வை, அது உன்னையே தின்னும்' என்ற பழமொழியைப் போன்றதுதான். அல்லாஹ்வின் மீது ஆணையாக, நாம் மதீனா திரும்பும்போது கண்ணியமானவர்கள் இழிவானவர்களை அங்கிருந்து வெளியேற்றுவார்கள்' என்றான். பிறகு அங்கிருந்த தன் மக்களிடம், 'அவர்களை உங்கள் நிலத்தில் குடியேற அனுமதித்து உங்கள் செல்வத்தைப் பகிர்ந்து கொடுத்தது உங்கள் தவறு. அவர்களை நீங்கள் கைவிட்டால் அவர்கள் வேறு இடத்திற்குச் சென்றுவிடுவார்கள்' என்றான். இதைச் சிறுவராக இருந்த ஸைத் பின் அர்கம் (ரழி) அவர்கள் கேட்டு நபி (ஸல்) அவர்களிடம் தெரிவித்தார். அப்போது நபி (ஸல்) அவர்களுடன் இருந்த உமர் (ரழி) அவர்கள், 'அல்லாஹ்வின் தூதரே! அப்பாத் பின் பிஷ்ர் (ரழி) அவர்களிடம் கூறி இவனது தலையை வெட்ட ஆணையிடுங்கள்' என்றார்கள். அதற்கு நபி (ஸல்) அவர்கள் பதிலளித்தார்கள்:<br />\r\n<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">فَكَيْفَ</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">تَحَدَّثَ</span> <span class=\"quran-arabic-font text-success\">النَّاسُ</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">عُمَرُ</span> <span class=\"quran-arabic-font text-success\">أَنَّ</span> <span class=\"quran-arabic-font text-success\">مُحَمَّدًا</span> <span class=\"quran-arabic-font text-success\">يَقْتُلُ</span> <span class=\"quran-arabic-font text-success\">أَصْحَابَهُ،</span> <span class=\"quran-arabic-font text-success\">لَا،</span> <span class=\"quran-arabic-font text-success\">وَلَكِنْ</span> <span class=\"quran-arabic-font text-success\">نَادِ</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">عُمَرُ</span> <span class=\"quran-arabic-font text-success\">الرَّحِيل</span>»<br />\r\n<br />\r\n<br />\r\n(உமரே! முஹம்மது தனது தோழர்களையே கொல்கிறார் என்று மக்கள் பேசிக் கொள்வார்களே! வேண்டாம், பயணத்தைத் தொடங்க மக்களுக்கு ஆணையிடுவீராக!) தனது பேச்சு நபி (ஸல்) அவர்களுக்குத் தெரிந்துவிட்டதை அறிந்த இப்னு உபய், அவரிடம் வந்து தான் அவ்வாறு கூறவில்லை என மறுத்தான். ஸைத் பின் அர்கம் (ரழி) அவர்கள் கூறிய அந்தப் பேச்சைத் தான் பேசவில்லை என அல்லாஹ்வின் மீது சத்தியம் செய்தான். அவன் ஒரு தலைவனாக இருந்ததால், மக்கள் நபி (ஸல்) அவர்களிடம், 'அல்லாஹ்வின் தூதரே! அந்தச் சிறுவன் தவறாகக் கருதியிருக்கலாம், சரியாகக் கேட்டிருக்காமல் இருக்கலாம்' என்றார்கள். நபி (ஸல்) அவர்கள் ஒரு வழக்கத்திற்கு மாறான நேரத்தில் பயணத்தைத் தொடங்கினார்கள். அப்போது உஸைத் பின் அல்-ஹுதைர் (ரழி) அவர்கள் நபி (ஸல்) அவர்களைச் சந்தித்து ஸலாம் கூறி, \"அல்லாஹ்வின் மீது ஆணையாக! நீங்கள் ஒரு அசாதாரண நேரத்தில் பயணத்தைத் தொடங்குகிறீர்கள்\" என்றார். அதற்கு நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَمَا</span> <span class=\"quran-arabic-font text-success\">بَلَغَكَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">صَاحِبُكَ</span> <span class=\"quran-arabic-font text-success\">ابْنُ</span> <span class=\"quran-arabic-font text-success\">أُبَيَ؟</span> <span class=\"quran-arabic-font text-success\">زَعَمَ</span> <span class=\"quran-arabic-font text-success\">أَنَّهُ</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">قَدِمَ</span> <span class=\"quran-arabic-font text-success\">الْمَدِينَةَ</span> <span class=\"quran-arabic-font text-success\">سَيُخْرِجُ</span> <span class=\"quran-arabic-font text-success\">الْأَعَزُّ</span> <span class=\"quran-arabic-font text-success\">مِنْهَا</span> <span class=\"quran-arabic-font text-success\">الْأَذَل</span>»<br />\r\n<br />\r\n<br />\r\n(உமது நண்பர் இப்னு உபய் கூறியது உமக்கு எட்டவில்லையா? மதீனா திரும்பினால் கண்ணியமானவர் இழிவானவரை அங்கிருந்து வெளியேற்றுவார் என அவன் கூறுகிறானே!) அதற்கு உஸைத் (ரழி) அவர்கள், \"அல்லாஹ்வின் தூதரே! கண்ணியமானவர் நீங்களே, அவன்தான் இழிவானவன்\" என்றார். மேலும், \"அவனிடம் மென்மையாக நடங்கள்; தாங்கள் இங்கு வருவதற்கு முன் அவனுக்கு முடிசூட்டவே மக்கள் முத்துக்களைச் சேகரித்துத் தயாராக இருந்தனர். அதனால் தாங்கள் அவனது அரச பதவியைப் பறித்துவிட்டதாக அவன் கருதுகிறான்\" என்றார். மக்கள் பேச்சைக் குறைக்க வேண்டும் என்பதற்காக நபி (ஸல்) அவர்கள் அன்றைய இரவு முழுவதும், அடுத்த நாள் காலை வரையிலும் தொடர்ந்து பயணம் செய்தார்கள். மக்கள் ஓய்வெடுக்க ஓரிடத்தில் இறங்கியதும், பயணக் களைப்பினால் உடனடியாகத் தூங்கிவிட்டனர். அப்போதுதான் ஸூரா அல்-முனாஃபிகூன் அருளப்பட்டது.<br />\r\n<br />\r\n<br />\r\nஅல்-ஹாஃபிழ் அபூ பக்ர் அல்-பைஹகீ, ஜாபிர் பின் அப்துல்லாஹ் (ரழி) அவர்கள் அறிவித்ததாகப் பதிவு செய்துள்ளார்: \"நாங்கள் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுடன் ஒரு போரில் இருந்தோம். அப்போது முஹாஜிர் ஒருவர் அன்சாரி ஒருவரை உதைக்க, அந்த அன்சாரி 'அன்சாரிகளே!' என்றும், முஹாஜிர் 'முஹாஜிர்களே!' என்றும் உதவிக்கு அழைத்தனர். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அதைக் கேட்டுவிட்டு கூறினார்கள்:<br />\r\n<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">بَالُ</span> <span class=\"quran-arabic-font text-success\">دَعْوَى</span> <span class=\"quran-arabic-font text-success\">الْجَاهِلِيَّةِ؟</span> <span class=\"quran-arabic-font text-success\">دَعُوهَا</span> <span class=\"quran-arabic-font text-success\">فَإِنَّهَا</span> <span class=\"quran-arabic-font text-success\">مُنْتِنَة</span>»<br />\r\n<br />\r\n<br />\r\n(இந்த அறியாமைக் கால - ஜாஹிலிய்யா - அழைப்பு என்ன? இதை விட்டுவிடுங்கள், ஏனெனில் இது மிகவும் அருவருப்பானது.) இதைக் கேட்ட அப்துல்லாஹ் பின் உபய், 'அவர்கள் (முஹாஜிர்கள்) இவ்வளவு துணிந்துவிட்டார்களா? அல்லாஹ்வின் மீது ஆணையாக, நாம் மதீனா திரும்பினால் கண்ணியமானவர் தாழ்ந்தவரை அங்கிருந்து வெளியேற்றுவார்' என்றான். அந்த நேரத்தில் அன்சாரிகளின் எண்ணிக்கை முஹாஜிர்களை விட அதிகமாக இருந்தது, ஆனால் பின்னர் முஹாஜிர்களின் எண்ணிக்கை அதிகரித்தது. இந்தச் செய்தி நபி (ஸல்) அவர்களுக்கு எட்டியபோது, உமர் (ரழி) அவர்கள் எழுந்து, 'அல்லாஹ்வின் தூதரே! இந்த நயவஞ்சகனின் தலையை வெட்ட என்னை அனுமதியுங்கள்!' என்றார்கள். அதற்கு நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">دَعْهُ،</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يَتَحَدَّثُ</span> <span class=\"quran-arabic-font text-success\">النَّاسُ</span> <span class=\"quran-arabic-font text-success\">أَنَّ</span> <span class=\"quran-arabic-font text-success\">مُحَمَّدًا</span> <span class=\"quran-arabic-font text-success\">يَقْتُلُ</span> <span class=\"quran-arabic-font text-success\">أَصْحَابَه</span>»<br />\r\n<br />\r\n<br />\r\n(அவனை விட்டுவிடுங்கள்; முஹம்மது தனது தோழர்களையே கொல்கிறார் என்று மக்கள் பேசக் கூடாது.)\" இமாம் அஹ்மத், புகாரி மற்றும் முஸ்லிம் இந்த ஹதீஸைப் பதிவு செய்துள்ளனர்.<br />\r\n<br />\r\n<br />\r\nஇக்ரிமா, இப்னு ஸைத் மற்றும் பலர் கூறுகிறார்கள்: நபி (ஸல்) அவர்களும் அவர்களது தோழர்களும் மதீனாவிற்குத் திரும்பியபோது, இப்னு உபய்யின் மகனான அப்துல்லாஹ் (ரழி) மதீனாவின் நுழைவாயிலில் தனது வாளைப் பிடித்துக்கொண்டு நின்றார். மக்கள் அவரைக் கடந்து சென்றனர், இறுதியில் அவரது தந்தை வந்தார். அப்துல்லாஹ் (ரழி) தனது தந்தையிடம், \"அப்படியே நில்லுங்கள்\" என்றார். தந்தை காரணம் கேட்க, அதற்கு அவரது மகன், \"அல்லாஹ்வின் மீது ஆணையாக! அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அனுமதிக்கும் வரை நீங்கள் உள்ளே நுழைய முடியாது. அவர்களே கண்ணியமானவர், நீங்கள்தான் இழிவானவர்\" என்றார். வழக்கமாகப் படையின் பின்வரிசையில் வரும் நபி (ஸல்) அவர்கள் அங்கே வந்தபோது, இப்னு உபய் தனது மகனைப் பற்றிப் புகாரளித்தார். ஆனால் அப்துல்லாஹ் (ரழி), \"அல்லாஹ்வின் தூதரே! நீங்கள் அனுமதிக்கும் வரை அவர் நுழையக்கூடாது\" என்றார். நபி (ஸல்) அவர்கள் அனுமதி அளித்த பிறகே, \"இப்போது நுழையுங்கள்\" என்று கூறித் தன் தந்தையை அனுமதித்தார்.<br />\r\n<br />\r\n<br />\r\nஅபூ பக்ர் அப்துல்லாஹ் பின் அஸ்-ஸுபைர் அல்-ஹுமைதி தனது முஸ்னதில் அபூ ஹாரூன் அல்-மதனியின் மூலம் அறிவிக்கிறார்: அப்துல்லாஹ் (ரழி) தன் தந்தையிடம், \"'அல்லாஹ்வின் தூதரே கண்ணியமானவர், நானே இழிவானவன்' என்று நீங்கள் கூறாத வரை மதீனாவிற்குள் நுழைய விடமாட்டேன்\" என்றார். நபி (ஸல்) அவர்கள் வந்தபோது, அப்துல்லாஹ் (ரழி) அவர்களிடம், \"அல்லாஹ்வின் தூதரே! என் தந்தையைக் கொல்ல நீங்கள் முடிவெடுத்திருப்பதாக அறிந்தேன். உங்களை உண்மையுடன் அனுப்பியவன் மீது சத்தியமாக, அவர் மீதுள்ள மரியாதையால் நான் அவரை ஒருபோதும் நேருக்கு நேராகக் கூடப் பார்த்ததில்லை. ஆனால் நீங்கள் விரும்பினால் நானே அவரது தலையை உங்களிடம் கொண்டு வருகிறேன். வேறொருவர் என் தந்தையைக் கொல்வதை நான் பார்க்க விரும்பவில்லை; (அவ்வாறு கொல்பவரை நான் பார்த்து ஆத்திரம் கொண்டு அவரைக் கொன்றுவிட்டால், ஒரு காஃபிருக்காக ஒரு முஃமினைக் கொன்று நான் நரகத்திற்குச் செல்ல நேரிடும்)\" என்றார். அதற்கு நபி (ஸல்) அவர்கள், \"இல்லை! நாம் அவருடன் நல்லவிதமாகவே நடந்து கொள்வோம்; அவர் நம்முடன் இருக்கும் காலமெல்லாம் அவருக்கு நல்ல தோழராகவே இருப்போம்\" என்று கூறினார்கள்.<br />\r\n<br />","text":"தங்களுக்காக மன்னிப்புத் தேடும்படி அல்லாஹ்வின் தூதரிடம் வேண்டுவதற்கு நயவஞ்சகர்கள் முன்வரவில்லை\n\r\n\n\r\n\n\r\nஅல்லாஹ்வின் சாபத்திற்குரிய நயவஞ்சகர்களைப் பற்றி கண்ணியத்திற்குரிய அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n\n\r\nوَإِذَا قِيلَ لَهُمْ تَعَالَوْاْ يَسْتَغْفِرْ لَكُمْ رَسُولُ اللَّهِ لَوَّوْاْ رُءُوسَهُمْ\n\r\n\n\r\n\n\r\n(அவர்களிடம்: \"வாருங்கள், அல்லாஹ்வின் தூதர் உங்களுக்காக அல்லாஹ்விடம் பாவமன்னிப்புத் தேடுவார்கள்\" எனக் கூறப்பட்டால், அவர்கள் தங்கள் தலைகளைத் திருப்பிக் கொள்கிறார்கள்.) அதாவது, அவர்கள் பெருமையின் காரணமாக இதைப் புறக்கணித்து, தாங்கள் அழைக்கப்படும் விஷயத்தை இழிவுபடுத்தி, அதிலிருந்து விலகிச் செல்கிறார்கள். இதனால்தான் அல்லாஹ் கூறினான்:\n\r\n\n\r\n\n\r\nوَرَأَيْتَهُمْ يَصُدُّونَ وَهُم مُّسْتَكْبِرُونَ\n\r\n\n\r\n\n\r\n(மேலும், அவர்கள் பெருமையுடன் தங்கள் முகங்களைத் திருப்பிக் கொள்வதை நீர் காண்பீர்.) அவர்களின் இத்தகைய நடத்தைக்காக அவர்களைத் தண்டிக்கும் விதமாக அல்லாஹ் கூறினான்:\n\r\n\n\r\n\n\r\nسَوَآءٌ عَلَيْهِمْ أَسْتَغْفَرْتَ لَهُمْ أَمْ لَمْ تَسْتَغْفِرْ لَهُمْ لَن يَغْفِرَ اللَّهُ لَهُمْ إِنَّ اللَّهَ لاَ يَهْدِى الْقَوْمَ الْفَـسِقِينَ\n\r\n\n\r\n\n\r\n(நீர் அவர்களுக்காகப் பாவமன்னிப்புத் தேடினாலும் அல்லது தேடாவிட்டாலும் அவர்களுக்குச் சமமே; அல்லாஹ் அவர்களை ஒருபோதும் மன்னிக்க மாட்டான். நிச்சயமாக, அல்லாஹ் வரம்பு மீறிய பாவிகளுக்கு நேர்வழி காட்டமாட்டான்.) ஸூரா பராஆவில் (அத்-தவ்பா) அல்லாஹ் கூறியது போன்று, இது குறித்த விளக்கம் அந்த அத்தியாயத்திலேயே ஏற்கனவே இடம்பெற்றுள்ளது. அது தொடர்பான சில ஹதீஸ்களை இங்கே நாம் குறிப்பிடுவோம். ஸலஃபுகள் (முன்னோர்) பலர் இந்த வசனங்கள் அனைத்தும் அப்துல்லாஹ் பின் உபய் பின் ஸலூல் விஷயத்திலேயே அருளப்பட்டதாகக் குறிப்பிட்டுள்ளனர். அல்லாஹ் நாடினால் இது குறித்து விரிவாகக் காண்போம்; அவன் மீதே நாம் முழுமையாகப் பாரத்தைச் சாட்டுகிறோம்.\n\r\n\n\r\n\n\r\nஹும் அல்லதீன யகூலூன...\n\r\n\n\r\n\n\r\nهُمُ الَّذِينَ يَقُولُونَ لاَ تُنفِقُواْ عَلَى مَنْ عِندَ رَسُولِ اللَّهِ حَتَّى يَنفَضُّواْ وَلِلَّهِ خَزَآئِنُ السَّمَـوَتِ وَالاٌّرْضِ وَلَـكِنَّ الْمُنَـفِقِينَ لاَ يَفْقَهُونَ - يَقُولُونَ لَئِن رَّجَعْنَا إِلَى الْمَدِينَةِ لَيُخْرِجَنَّ الاٌّعَزُّ مِنْهَا الاٌّذَلَّ وَلِلَّهِ الْعِزَّةُ وَلِرَسُولِهِ وَلِلْمُؤْمِنِينَ وَلَـكِنَّ الْمُنَـفِقِينَ لاَ يَعْلَمُونَ\n\r\n\n\r\n\n\r\n(அவர்கள்தான்: \"அல்லாஹ்வின் தூதருடன் இருப்பவர்கள் மீது (பொருட்களைச்) செலவு செய்யாதீர்கள்; அதனால் அவர்கள் (அவரை விட்டுப்) பிரிந்து சென்றுவிடுவார்கள்\" என்று கூறுகிறார்கள். வானங்கள் மற்றும் பூமியின் பொக்கிஷங்கள் அல்லாஹ்வுக்கே உரியன. எனினும், இந்நயவஞ்சகர்கள் விளங்கிக்கொள்ள மாட்டார்கள். அவர்கள்: \"நாங்கள் மதீனாவுக்குத் திரும்பினால், கண்ணியமானவர் இழிவானவரை அங்கிருந்து வெளியேற்றிவிடுவார்\" என்று கூறுகிறார்கள். கண்ணியம் அல்லாஹ்வுக்கும், அவனது தூதருக்கும், நம்பிக்கையாளர்களுக்கும் உரியதாகும். எனினும், இந்நயவஞ்சகர்கள் அறியமாட்டார்கள்.)\n\r\n\n\r\n\n\r\nமுஹம்மது பின் இஸ்ஹாக் அவர்கள் தனது 'அஸ்-ஸீரா' நூலில் பின்வருமாறு கூறுகிறார்கள்: \"உஹுதுப் போர் முடிந்த பிறகு, நபி (ஸல்) அவர்கள் மதீனாவிற்குத் திரும்பினார்கள். இப்னு ஷிஹாப் எனக்கு அறிவித்தபடி, அப்துல்லாஹ் பின் உபய் பின் ஸலூல் ஒவ்வொரு வெள்ளிக்கிழமையும் ஜுமுஆ குத்பாவுக்கு முன்பாக நபி (ஸல்) அவர்கள் மின்பரில் அமர்ந்திருக்கும்போது எழுந்து நிற்பார். அவர் தனது சமூகத்தின் தலைவராக இருந்ததால் யாரும் அவரைத் தடுக்க மாட்டார்கள். அவர் கூறுவார்: 'மக்களே! உங்களிடையே அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இருக்கிறார்கள். அவர்கள் மூலம் அல்லாஹ் நமக்குக் கண்ணியத்தை அளித்துள்ளான், உங்களுக்கு வலிமையை வழங்கியுள்ளான். அவருக்கு ஆதரவளியுங்கள், அவரைக் கண்ணியப்படுத்துங்கள், அவருக்குச் செவிசாய்த்துக் கீழ்ப்படியுங்கள்.' இவ்வாறு கூறிவிட்டு அவர் அமர்வார். உஹுதுப் போரில் மூன்றில் ஒரு பங்கு படையுடன் அவர் பாதியிலேயே மதீனாவிற்குத் திரும்பிச் சென்ற பிறகும், அதே போன்று பேச எழுந்து நின்றார். ஆனால் முஸ்லிம்கள் அவரது ஆடையைப் பிடித்து இழுத்து, 'அல்லாஹ்வின் எதிரியே! அமர். நீ செய்த காரியத்திற்குப் பிறகு இங்கிருந்து பேச உனக்குத் தகுதியில்லை' என்றார்கள். உடனே அவர் மக்களின் வரிசைகளைத் தாண்டி மஸ்ஜிதை விட்டு வெளியேறினார். 'அல்லாஹ்வின் மீது ஆணையாக, நான் அவருக்கு ஆதரவாகப் பேச விரும்பியபோது ஏதோ ஒரு பெரும் குற்றத்தைச் செய்தது போன்று என்னை நடத்துகிறார்களே' என்று முணுமுணுத்துச் சென்றார். மஸ்ஜிதின் வாயிலில் நின்றிருந்த அன்சாரிகள் என்ன நடந்தது எனக் கேட்டபோது, 'நான் அவருக்கு ஆதரவாகப் பேச எழுந்தேன், ஆனால் அவரது தோழர்கள் என் மேல் பாய்ந்து என்னைக் கண்டித்தார்கள்' என்றார். அதற்கு அவர்கள், 'உமக்குக் கேடுதான்! திரும்பிச் செல்லும், அல்லாஹ்வின் தூதர் (ஸல்) உம்மை மன்னிக்கும்படி அல்லாஹ்விடம் வேண்டுவார்கள்' என்றனர். ஆனால் அவரோ, 'அல்லாஹ்வின் மீது ஆணையாக, அவர் எனக்காக மன்னிப்புக் கேட்பதை நான் விரும்பவில்லை' என்று கூறிவிட்டார்.\"\n\r\n\n\r\n\n\r\nகதாதா மற்றும் அஸ்-ஸுத்தி ஆகியோர் கூறுகிறார்கள்: \"இந்த வசனம் அப்துல்லாஹ் பின் உபய் குறித்து அருளப்பட்டது. அவனது இளம் உறவினர் ஒருவர் நபி (ஸல்) அவர்களிடம் வந்து, அப்துல்லாஹ் பேசிய ஒரு மோசமான பேச்சைத் தெரிவித்தார். நபி (ஸல்) அவர்கள் அவனை அழைத்தபோது, தான் அவ்வாறு கூறவில்லை என அல்லாஹ்வின் மீது சத்தியம் செய்தான். அன்சாரிகளும் அந்தச் சிறுவனைக் கண்டித்தனர். ஆனால் அல்லாஹ் உண்மையை (வசனமாக) இறக்கினான். பிறகு அவனிடம் 'அல்லாஹ்வின் தூதரிடம் செல்லும்' எனக் கூறப்பட்டபோது, அவன் தன் தலையைத் திருப்பிக்கொண்டு அதைச் செய்ய மறுத்துவிட்டான்.\"\n\r\n\n\r\n\n\r\nமுஹம்மது பின் இஸ்ஹாக், முஹம்மது பின் யஹ்யா பின் ஹிப்பான், அப்துல்லாஹ் பின் அபீ பக்ர் மற்றும் ஆஸிம் பின் உமர் பின் கதாதா ஆகியோர் பனூ முஸ்தலிக் போர் பற்றி அறிவிக்கிறார்கள்: நபி (ஸல்) அவர்கள் அங்கு தங்கியிருந்தபோது, உமர் (ரழி) அவர்களின் பணியாளரான ஜஹ்ஜா பின் ஸயீத் அல்-கிஃபாரியும், ஸினான் பின் வப்ர் அல்-ஜுஹனீயும் நீருற்றைப் பயன்படுத்துவதில் சண்டையிட்டுக் கொண்டனர். ஸினான் 'அன்சாரிகளே!' என்றும், ஜஹ்ஜா 'முஹாஜிர்களே!' என்றும் உதவிக்கு அழைத்தனர். அப்போது ஸைத் பின் அர்கம் (ரழி) அவர்களும் சில அன்சாரிகளும் அப்துல்லாஹ் பின் உபய்யுடன் அமர்ந்திருந்தனர். நடந்ததைக் கேட்ட அவன், 'அவர்கள் நம் ஊரிலேயே நமக்குத் தொந்தரவு தருகிறார்கள். நமக்கும் இந்த வந்தேறிக் குறைஷிகளுக்கும் உள்ள நிலை: 'உன் நாயைக் கொழுக்க வை, அது உன்னையே தின்னும்' என்ற பழமொழியைப் போன்றதுதான். அல்லாஹ்வின் மீது ஆணையாக, நாம் மதீனா திரும்பும்போது கண்ணியமானவர்கள் இழிவானவர்களை அங்கிருந்து வெளியேற்றுவார்கள்' என்றான். பிறகு அங்கிருந்த தன் மக்களிடம், 'அவர்களை உங்கள் நிலத்தில் குடியேற அனுமதித்து உங்கள் செல்வத்தைப் பகிர்ந்து கொடுத்தது உங்கள் தவறு. அவர்களை நீங்கள் கைவிட்டால் அவர்கள் வேறு இடத்திற்குச் சென்றுவிடுவார்கள்' என்றான். இதைச் சிறுவராக இருந்த ஸைத் பின் அர்கம் (ரழி) அவர்கள் கேட்டு நபி (ஸல்) அவர்களிடம் தெரிவித்தார். அப்போது நபி (ஸல்) அவர்களுடன் இருந்த உமர் (ரழி) அவர்கள், 'அல்லாஹ்வின் தூதரே! அப்பாத் பின் பிஷ்ர் (ரழி) அவர்களிடம் கூறி இவனது தலையை வெட்ட ஆணையிடுங்கள்' என்றார்கள். அதற்கு நபி (ஸல்) அவர்கள் பதிலளித்தார்கள்:\n\r\n\n\r\n\n\r\n«فَكَيْفَ إِذَا تَحَدَّثَ النَّاسُ يَا عُمَرُ أَنَّ مُحَمَّدًا يَقْتُلُ أَصْحَابَهُ، لَا، وَلَكِنْ نَادِ يَا عُمَرُ الرَّحِيل»\n\r\n\n\r\n\n\r\n(உமரே! முஹம்மது தனது தோழர்களையே கொல்கிறார் என்று மக்கள் பேசிக் கொள்வார்களே! வேண்டாம், பயணத்தைத் தொடங்க மக்களுக்கு ஆணையிடுவீராக!) தனது பேச்சு நபி (ஸல்) அவர்களுக்குத் தெரிந்துவிட்டதை அறிந்த இப்னு உபய், அவரிடம் வந்து தான் அவ்வாறு கூறவில்லை என மறுத்தான். ஸைத் பின் அர்கம் (ரழி) அவர்கள் கூறிய அந்தப் பேச்சைத் தான் பேசவில்லை என அல்லாஹ்வின் மீது சத்தியம் செய்தான். அவன் ஒரு தலைவனாக இருந்ததால், மக்கள் நபி (ஸல்) அவர்களிடம், 'அல்லாஹ்வின் தூதரே! அந்தச் சிறுவன் தவறாகக் கருதியிருக்கலாம், சரியாகக் கேட்டிருக்காமல் இருக்கலாம்' என்றார்கள். நபி (ஸல்) அவர்கள் ஒரு வழக்கத்திற்கு மாறான நேரத்தில் பயணத்தைத் தொடங்கினார்கள். அப்போது உஸைத் பின் அல்-ஹுதைர் (ரழி) அவர்கள் நபி (ஸல்) அவர்களைச் சந்தித்து ஸலாம் கூறி, \"அல்லாஹ்வின் மீது ஆணையாக! நீங்கள் ஒரு அசாதாரண நேரத்தில் பயணத்தைத் தொடங்குகிறீர்கள்\" என்றார். அதற்கு நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n\n\r\n«أَمَا بَلَغَكَ مَا قَالَ صَاحِبُكَ ابْنُ أُبَيَ؟ زَعَمَ أَنَّهُ إِذَا قَدِمَ الْمَدِينَةَ سَيُخْرِجُ الْأَعَزُّ مِنْهَا الْأَذَل»\n\r\n\n\r\n\n\r\n(உமது நண்பர் இப்னு உபய் கூறியது உமக்கு எட்டவில்லையா? மதீனா திரும்பினால் கண்ணியமானவர் இழிவானவரை அங்கிருந்து வெளியேற்றுவார் என அவன் கூறுகிறானே!) அதற்கு உஸைத் (ரழி) அவர்கள், \"அல்லாஹ்வின் தூதரே! கண்ணியமானவர் நீங்களே, அவன்தான் இழிவானவன்\" என்றார். மேலும், \"அவனிடம் மென்மையாக நடங்கள்; தாங்கள் இங்கு வருவதற்கு முன் அவனுக்கு முடிசூட்டவே மக்கள் முத்துக்களைச் சேகரித்துத் தயாராக இருந்தனர். அதனால் தாங்கள் அவனது அரச பதவியைப் பறித்துவிட்டதாக அவன் கருதுகிறான்\" என்றார். மக்கள் பேச்சைக் குறைக்க வேண்டும் என்பதற்காக நபி (ஸல்) அவர்கள் அன்றைய இரவு முழுவதும், அடுத்த நாள் காலை வரையிலும் தொடர்ந்து பயணம் செய்தார்கள். மக்கள் ஓய்வெடுக்க ஓரிடத்தில் இறங்கியதும், பயணக் களைப்பினால் உடனடியாகத் தூங்கிவிட்டனர். அப்போதுதான் ஸூரா அல்-முனாஃபிகூன் அருளப்பட்டது.\n\r\n\n\r\n\n\r\nஅல்-ஹாஃபிழ் அபூ பக்ர் அல்-பைஹகீ, ஜாபிர் பின் அப்துல்லாஹ் (ரழி) அவர்கள் அறிவித்ததாகப் பதிவு செய்துள்ளார்: \"நாங்கள் அல்லாஹ்வின் தூதர் (ஸல்) அவர்களுடன் ஒரு போரில் இருந்தோம். அப்போது முஹாஜிர் ஒருவர் அன்சாரி ஒருவரை உதைக்க, அந்த அன்சாரி 'அன்சாரிகளே!' என்றும், முஹாஜிர் 'முஹாஜிர்களே!' என்றும் உதவிக்கு அழைத்தனர். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அதைக் கேட்டுவிட்டு கூறினார்கள்:\n\r\n\n\r\n\n\r\n«مَا بَالُ دَعْوَى الْجَاهِلِيَّةِ؟ دَعُوهَا فَإِنَّهَا مُنْتِنَة»\n\r\n\n\r\n\n\r\n(இந்த அறியாமைக் கால - ஜாஹிலிய்யா - அழைப்பு என்ன? இதை விட்டுவிடுங்கள், ஏனெனில் இது மிகவும் அருவருப்பானது.) இதைக் கேட்ட அப்துல்லாஹ் பின் உபய், 'அவர்கள் (முஹாஜிர்கள்) இவ்வளவு துணிந்துவிட்டார்களா? அல்லாஹ்வின் மீது ஆணையாக, நாம் மதீனா திரும்பினால் கண்ணியமானவர் தாழ்ந்தவரை அங்கிருந்து வெளியேற்றுவார்' என்றான். அந்த நேரத்தில் அன்சாரிகளின் எண்ணிக்கை முஹாஜிர்களை விட அதிகமாக இருந்தது, ஆனால் பின்னர் முஹாஜிர்களின் எண்ணிக்கை அதிகரித்தது. இந்தச் செய்தி நபி (ஸல்) அவர்களுக்கு எட்டியபோது, உமர் (ரழி) அவர்கள் எழுந்து, 'அல்லாஹ்வின் தூதரே! இந்த நயவஞ்சகனின் தலையை வெட்ட என்னை அனுமதியுங்கள்!' என்றார்கள். அதற்கு நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n\n\r\n«دَعْهُ، لَا يَتَحَدَّثُ النَّاسُ أَنَّ مُحَمَّدًا يَقْتُلُ أَصْحَابَه»\n\r\n\n\r\n\n\r\n(அவனை விட்டுவிடுங்கள்; முஹம்மது தனது தோழர்களையே கொல்கிறார் என்று மக்கள் பேசக் கூடாது.)\" இமாம் அஹ்மத், புகாரி மற்றும் முஸ்லிம் இந்த ஹதீஸைப் பதிவு செய்துள்ளனர்.\n\r\n\n\r\n\n\r\nஇக்ரிமா, இப்னு ஸைத் மற்றும் பலர் கூறுகிறார்கள்: நபி (ஸல்) அவர்களும் அவர்களது தோழர்களும் மதீனாவிற்குத் திரும்பியபோது, இப்னு உபய்யின் மகனான அப்துல்லாஹ் (ரழி) மதீனாவின் நுழைவாயிலில் தனது வாளைப் பிடித்துக்கொண்டு நின்றார். மக்கள் அவரைக் கடந்து சென்றனர், இறுதியில் அவரது தந்தை வந்தார். அப்துல்லாஹ் (ரழி) தனது தந்தையிடம், \"அப்படியே நில்லுங்கள்\" என்றார். தந்தை காரணம் கேட்க, அதற்கு அவரது மகன், \"அல்லாஹ்வின் மீது ஆணையாக! அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் அனுமதிக்கும் வரை நீங்கள் உள்ளே நுழைய முடியாது. அவர்களே கண்ணியமானவர், நீங்கள்தான் இழிவானவர்\" என்றார். வழக்கமாகப் படையின் பின்வரிசையில் வரும் நபி (ஸல்) அவர்கள் அங்கே வந்தபோது, இப்னு உபய் தனது மகனைப் பற்றிப் புகாரளித்தார். ஆனால் அப்துல்லாஹ் (ரழி), \"அல்லாஹ்வின் தூதரே! நீங்கள் அனுமதிக்கும் வரை அவர் நுழையக்கூடாது\" என்றார். நபி (ஸல்) அவர்கள் அனுமதி அளித்த பிறகே, \"இப்போது நுழையுங்கள்\" என்று கூறித் தன் தந்தையை அனுமதித்தார்.\n\r\n\n\r\n\n\r\nஅபூ பக்ர் அப்துல்லாஹ் பின் அஸ்-ஸுபைர் அல்-ஹுமைதி தனது முஸ்னதில் அபூ ஹாரூன் அல்-மதனியின் மூலம் அறிவிக்கிறார்: அப்துல்லாஹ் (ரழி) தன் தந்தையிடம், \"'அல்லாஹ்வின் தூதரே கண்ணியமானவர், நானே இழிவானவன்' என்று நீங்கள் கூறாத வரை மதீனாவிற்குள் நுழைய விடமாட்டேன்\" என்றார். நபி (ஸல்) அவர்கள் வந்தபோது, அப்துல்லாஹ் (ரழி) அவர்களிடம், \"அல்லாஹ்வின் தூதரே! என் தந்தையைக் கொல்ல நீங்கள் முடிவெடுத்திருப்பதாக அறிந்தேன். உங்களை உண்மையுடன் அனுப்பியவன் மீது சத்தியமாக, அவர் மீதுள்ள மரியாதையால் நான் அவரை ஒருபோதும் நேருக்கு நேராகக் கூடப் பார்த்ததில்லை. ஆனால் நீங்கள் விரும்பினால் நானே அவரது தலையை உங்களிடம் கொண்டு வருகிறேன். வேறொருவர் என் தந்தையைக் கொல்வதை நான் பார்க்க விரும்பவில்லை; (அவ்வாறு கொல்பவரை நான் பார்த்து ஆத்திரம் கொண்டு அவரைக் கொன்றுவிட்டால், ஒரு காஃபிருக்காக ஒரு முஃமினைக் கொன்று நான் நரகத்திற்குச் செல்ல நேரிடும்)\" என்றார். அதற்கு நபி (ஸல்) அவர்கள், \"இல்லை! நாம் அவருடன் நல்லவிதமாகவே நடந்து கொள்வோம்; அவர் நம்முடன் இருக்கும் காலமெல்லாம் அவருக்கு நல்ல தோழராகவே இருப்போம்\" என்று கூறினார்கள்."},"9":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=63&ayah=11\" class=\"link\">63:11</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 63:11 ஐ பார்க்கவும்"},"10":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=63&ayah=11\" class=\"link\">63:11</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 63:11 ஐ பார்க்கவும்"},"11":{"html":"<strong>உலக வாழ்க்கை விவகாரங்களில் அதிகக் கவனம் செலுத்தாமல் இருப்பதன் மற்றும் தர்மம் செய்வதன் முக்கியத்துவம்</strong><br />\r\n<br />\r\nகண்ணியமிக்க அல்லாஹ், தனது இறைநம்பிக்கையுள்ள அடியார்களைத் தன்னை அதிகமாக நினைவு கூருமாறும், தங்களது செல்வங்களிலும் பிள்ளைகளிலும் மிதமிஞ்சி மூழ்கிவிடுவதன் மூலம் தன்னை நினைவுகூருவதிலிருந்து திசைதிருப்பப்படாமல் இருக்குமாறும் கட்டளையிடுகிறான். எவர்கள் இந்த உலக வாழ்க்கையிலும், அதன் இன்பங்களிலும் அதன் கவர்ச்சிகளிலும் மூழ்கி, எந்த நோக்கத்திற்காக அவர்கள் படைக்கப்பட்டார்களோ, அந்த அல்லாஹ்வின் வழிபாட்டிலிருந்தும் அவனை நினைவுகூருவதிலிருந்தும் திசைதிருப்பப்பட்டார்களோ, அவர்கள் நஷ்டவாளர்களில் சேருவார்கள் என்று அல்லாஹ் அவர்களுக்குத் தெரிவிக்கிறான். அவர்கள் மறுமை நாளில் தங்களையும், தங்கள் குடும்பத்தினரையும் இழந்துவிடுவார்கள்.<br />\r\n<br />\r\nஅல்லாஹ் தனது பாதையில் செலவு செய்யுமாறு இறைநம்பிக்கையாளர்களை ஊக்குவிக்கிறான்,<span class=\"quran-arabic-font text-success\">﴾وَأَنفِقُواْ</span> <span class=\"quran-arabic-font text-success\">مِمَّا</span> <span class=\"quran-arabic-font text-success\">رَزَقْنَاكُم</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">قَبْلِ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يَأْتِىَ</span> <span class=\"quran-arabic-font text-success\">أَحَدَكُمُ</span> <span class=\"quran-arabic-font text-success\">الْمَوْتُ</span> <span class=\"quran-arabic-font text-success\">فَيَقُولَ</span> <span class=\"quran-arabic-font text-success\">رَبِّ</span> <span class=\"quran-arabic-font text-success\">لَوْلا</span> <span class=\"quran-arabic-font text-success\">أَخَّرْتَنِى</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">أَجَلٍ</span> <span class=\"quran-arabic-font text-success\">قَرِيبٍ</span> <span class=\"quran-arabic-font text-success\">فَأَصَّدَّقَ</span> <span class=\"quran-arabic-font text-success\">وَأَكُن</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">الصَّالِحِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n(உங்களுக்கு நாம் வழங்கியவற்றிலிருந்து, உங்களில் ஒருவருக்கு மரணம் வருவதற்கு முன்பாகவே நீங்கள் செலவு செய்யுங்கள்; அப்போது அவர் கூறுவார்: \"என் இறைவா! நீ எனக்கு ஒரு சிறிது காலம் அவகாசம் அளித்திருக்கக் கூடாதா, அப்படியாயின் நான் தர்மம் செய்து, நல்லோர்களில் ஒருவனாக ஆகியிருப்பேனே!\")<br />\r\n<br />\r\nநிச்சயமாக, குறைபாடுகளில் வீழ்ந்துவிட்ட ஒவ்வொரு மனிதனும் தனது மரணத் தருவாயில் அதற்காக வருந்துவான். தான் இன்னும் சிறப்பாகச் செயல்படுவதற்கும், தவறவிட்ட நன்மைகளை அடைவதற்கும் ஒரு குறுகிய கால அவகாசத்தையாவது அவன் வேண்டுவான். இல்லை, உண்மையில் எது நடந்துவிட்டதோ அது நடந்துவிட்டது; வரவிருப்பது நிச்சயமாக வந்தே தீரும். ஒவ்வொருவரும் தத்தமது தவறுகளுக்குப் பொறுப்பாக்கப்படுவார்கள். நிராகரிப்பாளர்களைப் பொறுத்தவரை, அல்லாஹ் அவர்களைப் பற்றிக் கூறியது போலவே அவர்கள் இருப்பார்கள்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَأَنذِرِ</span> <span class=\"quran-arabic-font text-success\">النَّاسَ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">يَأْتِيهِمُ</span> <span class=\"quran-arabic-font text-success\">الْعَذَابُ</span> <span class=\"quran-arabic-font text-success\">فَيَقُولُ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ظَلَمُواْ</span> <span class=\"quran-arabic-font text-success\">رَبَّنَآ</span> <span class=\"quran-arabic-font text-success\">أَخِّرْنَآ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">أَجَلٍ</span> <span class=\"quran-arabic-font text-success\">قَرِيبٍ</span> <span class=\"quran-arabic-font text-success\">نُّجِبْ</span> <span class=\"quran-arabic-font text-success\">دَعْوَتَكَ</span> <span class=\"quran-arabic-font text-success\">وَنَتَّبِعِ</span> <span class=\"quran-arabic-font text-success\">الرُّسُلَ</span> <span class=\"quran-arabic-font text-success\">أَوَلَمْ</span> <span class=\"quran-arabic-font text-success\">تَكُونُواْ</span> <span class=\"quran-arabic-font text-success\">أَقْسَمْتُمْ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">قَبْلُ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">زَوَالٍ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n(வேதனை தங்களுக்கு வரும் அந்த நாளைப் பற்றி மனிதர்களுக்கு நீர் எச்சரிக்கை செய்வீராக! அப்போது அநீதி இழைத்தவர்கள் கூறுவார்கள்: \"எங்கள் இறைவா! எங்களுக்குச் சிறிது காலம் அவகாசம் அளிப்பாயாக! நாங்கள் உனது அழைப்பிற்குப் பதிலளித்து, இத்தூதர்களைப் பின்பற்றுவோம்!\" (அதற்கு அவர்களுக்குக் கூறப்படும்:) \"நிச்சயமாக உங்களுக்கு அழிவே ஏற்படாது என்று இதற்கு முன்னர் நீங்கள் சத்தியம் செய்து கொண்டிருக்கவில்லையா?\") (<a href=\"qurandisp.php?sura=14&ayah=44\" class=\"link\">14:44</a>), மேலும்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾حَتَّى</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">جَآءَ</span> <span class=\"quran-arabic-font text-success\">أَحَدَهُمُ</span> <span class=\"quran-arabic-font text-success\">الْمَوْتُ</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">رَبِّ</span> <span class=\"quran-arabic-font text-success\">ارْجِعُونِ</span> - <span class=\"quran-arabic-font text-success\">لَعَلِّى</span> <span class=\"quran-arabic-font text-success\">أَعْمَلُ</span> <span class=\"quran-arabic-font text-success\">صَالِحاً</span> <span class=\"quran-arabic-font text-success\">فِيمَا</span> <span class=\"quran-arabic-font text-success\">تَرَكْتُ</span> <span class=\"quran-arabic-font text-success\">كَلاَّ</span> <span class=\"quran-arabic-font text-success\">إِنَّهَا</span> <span class=\"quran-arabic-font text-success\">كَلِمَةٌ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">قَآئِلُهَا</span> <span class=\"quran-arabic-font text-success\">وَمِن</span> <span class=\"quran-arabic-font text-success\">وَرَآئِهِمْ</span> <span class=\"quran-arabic-font text-success\">بَرْزَخٌ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">يَوْمِ</span> <span class=\"quran-arabic-font text-success\">يُبْعَثُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n(முடிவில், அவர்களில் ஒருவருக்கு மரணம் வரும்போது அவர்: \"என் இறைவா! என்னைத் திரும்ப (உலகிற்கு) அனுப்பி வைப்பாயாக! நான் விட்டு வந்தவற்றில் நற்செயல்களைச் செய்வதற்காக!\" என்று கூறுவார். அவ்வாறில்லை! நிச்சயமாக இது அவர் கூறும் வெறும் வார்த்தையே தவிர வேறில்லை! அவர்கள் மீண்டும் எழுப்பப்படும் நாள் வரை அவர்களுக்குப் பின்னால் 'பர்ஸக்' (திரை) ஒன்று இருக்கிறது.) (<a href=\"qurandisp.php?sura=23&ayah=99\" class=\"link\">23:99</a>-100)<br />\r\n<br />\r\nபிறகு அல்லாஹ் கூறினான்;<span class=\"quran-arabic-font text-success\">﴾وَلَن</span> <span class=\"quran-arabic-font text-success\">يُؤَخِّرَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">نَفْساً</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">جَآءَ</span> <span class=\"quran-arabic-font text-success\">أَجَلُهَآ</span> <span class=\"quran-arabic-font text-success\">وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">خَبِيرٌ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">تَعْمَلُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n(எந்த ஓர் ஆத்மாவுக்கும் அதற்கென நிர்ணயிக்கப்பட்ட தவணை வந்துவிட்டால், அல்லாஹ் அவகாசம் அளிக்கவே மாட்டான். அல்லாஹ் நீங்கள் செய்பவற்றை நன்கு அறிந்தவன்.)<br />\r\n<br />\r\nஅதாவது, மரணத்தின் நேரம் வந்துவிட்டால், யாருக்கும் அவகாசம் வழங்கப்பட மாட்டாது. நிச்சயமாக, அவர்கள் முன்பு செய்தவற்றை அவன் நன்கு அறிந்தவன். அல்லாஹ் கூறினான்,<span class=\"quran-arabic-font text-success\">﴾وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">خَبِيرٌ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">تَعْمَلُونَ﴿</span><br />\r\n(மேலும், நீங்கள் செய்பவற்றை அல்லாஹ் நன்கு அறிந்தவன்.)<br />\r\n<br />\r\nஇது ஸூரத்துல் முனாஃபிகூனின் தஃப்ஸீரின் நிறைவாகும். எல்லாப் புகழும் நன்றியும் அல்லாஹ்வுக்கே உரியது. அனைத்து வெற்றியும் தவறுகளிலிருந்து பாதுகாப்பும் அவனிடமிருந்தே உண்டாகின்றன.<br />\r\n<br />\r\n<br />\r\n<br />","text":"உலக வாழ்க்கை விவகாரங்களில் அதிகக் கவனம் செலுத்தாமல் இருப்பதன் மற்றும் தர்மம் செய்வதன் முக்கியத்துவம்\n\r\n\n\r\nகண்ணியமிக்க அல்லாஹ், தனது இறைநம்பிக்கையுள்ள அடியார்களைத் தன்னை அதிகமாக நினைவு கூருமாறும், தங்களது செல்வங்களிலும் பிள்ளைகளிலும் மிதமிஞ்சி மூழ்கிவிடுவதன் மூலம் தன்னை நினைவுகூருவதிலிருந்து திசைதிருப்பப்படாமல் இருக்குமாறும் கட்டளையிடுகிறான். எவர்கள் இந்த உலக வாழ்க்கையிலும், அதன் இன்பங்களிலும் அதன் கவர்ச்சிகளிலும் மூழ்கி, எந்த நோக்கத்திற்காக அவர்கள் படைக்கப்பட்டார்களோ, அந்த அல்லாஹ்வின் வழிபாட்டிலிருந்தும் அவனை நினைவுகூருவதிலிருந்தும் திசைதிருப்பப்பட்டார்களோ, அவர்கள் நஷ்டவாளர்களில் சேருவார்கள் என்று அல்லாஹ் அவர்களுக்குத் தெரிவிக்கிறான். அவர்கள் மறுமை நாளில் தங்களையும், தங்கள் குடும்பத்தினரையும் இழந்துவிடுவார்கள்.\n\r\n\n\r\nஅல்லாஹ் தனது பாதையில் செலவு செய்யுமாறு இறைநம்பிக்கையாளர்களை ஊக்குவிக்கிறான்,﴾وَأَنفِقُواْ مِمَّا رَزَقْنَاكُم مِّن قَبْلِ أَن يَأْتِىَ أَحَدَكُمُ الْمَوْتُ فَيَقُولَ رَبِّ لَوْلا أَخَّرْتَنِى إِلَى أَجَلٍ قَرِيبٍ فَأَصَّدَّقَ وَأَكُن مِّنَ الصَّالِحِينَ ﴿\n\r\n(உங்களுக்கு நாம் வழங்கியவற்றிலிருந்து, உங்களில் ஒருவருக்கு மரணம் வருவதற்கு முன்பாகவே நீங்கள் செலவு செய்யுங்கள்; அப்போது அவர் கூறுவார்: \"என் இறைவா! நீ எனக்கு ஒரு சிறிது காலம் அவகாசம் அளித்திருக்கக் கூடாதா, அப்படியாயின் நான் தர்மம் செய்து, நல்லோர்களில் ஒருவனாக ஆகியிருப்பேனே!\")\n\r\n\n\r\nநிச்சயமாக, குறைபாடுகளில் வீழ்ந்துவிட்ட ஒவ்வொரு மனிதனும் தனது மரணத் தருவாயில் அதற்காக வருந்துவான். தான் இன்னும் சிறப்பாகச் செயல்படுவதற்கும், தவறவிட்ட நன்மைகளை அடைவதற்கும் ஒரு குறுகிய கால அவகாசத்தையாவது அவன் வேண்டுவான். இல்லை, உண்மையில் எது நடந்துவிட்டதோ அது நடந்துவிட்டது; வரவிருப்பது நிச்சயமாக வந்தே தீரும். ஒவ்வொருவரும் தத்தமது தவறுகளுக்குப் பொறுப்பாக்கப்படுவார்கள். நிராகரிப்பாளர்களைப் பொறுத்தவரை, அல்லாஹ் அவர்களைப் பற்றிக் கூறியது போலவே அவர்கள் இருப்பார்கள்,\n\r\n\n\r\n﴾وَأَنذِرِ النَّاسَ يَوْمَ يَأْتِيهِمُ الْعَذَابُ فَيَقُولُ الَّذِينَ ظَلَمُواْ رَبَّنَآ أَخِّرْنَآ إِلَى أَجَلٍ قَرِيبٍ نُّجِبْ دَعْوَتَكَ وَنَتَّبِعِ الرُّسُلَ أَوَلَمْ تَكُونُواْ أَقْسَمْتُمْ مِّن قَبْلُ مَا لَكُمْ مِّن زَوَالٍ ﴿\n\r\n(வேதனை தங்களுக்கு வரும் அந்த நாளைப் பற்றி மனிதர்களுக்கு நீர் எச்சரிக்கை செய்வீராக! அப்போது அநீதி இழைத்தவர்கள் கூறுவார்கள்: \"எங்கள் இறைவா! எங்களுக்குச் சிறிது காலம் அவகாசம் அளிப்பாயாக! நாங்கள் உனது அழைப்பிற்குப் பதிலளித்து, இத்தூதர்களைப் பின்பற்றுவோம்!\" (அதற்கு அவர்களுக்குக் கூறப்படும்:) \"நிச்சயமாக உங்களுக்கு அழிவே ஏற்படாது என்று இதற்கு முன்னர் நீங்கள் சத்தியம் செய்து கொண்டிருக்கவில்லையா?\") (14:44), மேலும்,\n\r\n\n\r\n﴾حَتَّى إِذَا جَآءَ أَحَدَهُمُ الْمَوْتُ قَالَ رَبِّ ارْجِعُونِ - لَعَلِّى أَعْمَلُ صَالِحاً فِيمَا تَرَكْتُ كَلاَّ إِنَّهَا كَلِمَةٌ هُوَ قَآئِلُهَا وَمِن وَرَآئِهِمْ بَرْزَخٌ إِلَى يَوْمِ يُبْعَثُونَ ﴿\n\r\n(முடிவில், அவர்களில் ஒருவருக்கு மரணம் வரும்போது அவர்: \"என் இறைவா! என்னைத் திரும்ப (உலகிற்கு) அனுப்பி வைப்பாயாக! நான் விட்டு வந்தவற்றில் நற்செயல்களைச் செய்வதற்காக!\" என்று கூறுவார். அவ்வாறில்லை! நிச்சயமாக இது அவர் கூறும் வெறும் வார்த்தையே தவிர வேறில்லை! அவர்கள் மீண்டும் எழுப்பப்படும் நாள் வரை அவர்களுக்குப் பின்னால் 'பர்ஸக்' (திரை) ஒன்று இருக்கிறது.) (23:99-100)\n\r\n\n\r\nபிறகு அல்லாஹ் கூறினான்;﴾وَلَن يُؤَخِّرَ اللَّهُ نَفْساً إِذَا جَآءَ أَجَلُهَآ وَاللَّهُ خَبِيرٌ بِمَا تَعْمَلُونَ ﴿\n\r\n(எந்த ஓர் ஆத்மாவுக்கும் அதற்கென நிர்ணயிக்கப்பட்ட தவணை வந்துவிட்டால், அல்லாஹ் அவகாசம் அளிக்கவே மாட்டான். அல்லாஹ் நீங்கள் செய்பவற்றை நன்கு அறிந்தவன்.)\n\r\n\n\r\nஅதாவது, மரணத்தின் நேரம் வந்துவிட்டால், யாருக்கும் அவகாசம் வழங்கப்பட மாட்டாது. நிச்சயமாக, அவர்கள் முன்பு செய்தவற்றை அவன் நன்கு அறிந்தவன். அல்லாஹ் கூறினான்,﴾وَاللَّهُ خَبِيرٌ بِمَا تَعْمَلُونَ﴿\n\r\n(மேலும், நீங்கள் செய்பவற்றை அல்லாஹ் நன்கு அறிந்தவன்.)\n\r\n\n\r\nஇது ஸூரத்துல் முனாஃபிகூனின் தஃப்ஸீரின் நிறைவாகும். எல்லாப் புகழும் நன்றியும் அல்லாஹ்வுக்கே உரியது. அனைத்து வெற்றியும் தவறுகளிலிருந்து பாதுகாப்பும் அவனிடமிருந்தே உண்டாகின்றன."}}};})(self);
